    "code": "KH",  
    "languages": [  
      "Khmer",  
      "English"  
    ],  
    "plate_note": "Modern plates are white with black text for private cars, yellow with black for commercial use, in landscape orientation. Left-side blue band with Cambodian flag and Khmer script province name, plus Arabic numerals. Older simple white plates remain on some vehicles.",  
    "scripts": [  
      "khmer",  
      "latin"  
    ],  
    "traffic_side": "right"  
  },  
  {  
    "code": "VN",  
    "languages": [  
      "Vietnamese"  
    ],  
    "plate_note": "White plate with black letters for private passenger cars. Landscape format, beginning with a single Latin letter (provincial code) followed by numerals. Other colors include blue (state), red (military), yellow (commercial).",  
    "scripts": [  
      "latin"  
    ],  
    "traffic_side": "right"  
  },  
  {  
    "code": "MY",  
    "languages": [  
      "Malay",  
      "English",  
      "Chinese",  
      "Tamil"  
    ],  
    "plate_note": "Black plate with white text is standard for private passenger cars. Landscape format, left side features the Malaysian flag and state name in Latin script, followed by numerals. Red (commercial), blue (taxi) etc. also used.",  
    "scripts": [  
      "latin",  
      "japanese_kana_kanji",  
      "tamil",  
      "arabic"  
    ],  
    "traffic_side": "left"  
  },  
  {  
    "code": "SG",  
    "languages": [  
      "English",  
      "Chinese",  
      "Malay",  
      "Tamil"  
    ],  
    "plate_note": "Front plate is generally white with black text; rear plate is yellow with black text for most vehicle classes. Landscape format, starting with a letter prefix (S, E, A, etc.) followed by numerals. Other color schemes apply to taxis, rental cars, etc.",  
    "scripts": [  
      "latin",  
      "chinese_simplified",  
      "tamil"  
    ],  
    "traffic_side": "left"  
  },  
  {  
    "code": "ID",  
    "languages": [  
      "Indonesian"  
    ],  
    "plate_note": "Current standard for private cars is a white plate with black text in landscape orientation, with the province name in Latin script on top, a lettered regional code on the left, and Arabic numerals in the center. Older black-plate/white-text versions are still seen on older vehicles. Commercial vehicles use yellow plates.",  
    "scripts": [  
      "latin"  
    ],  
    "traffic_side": "left"  
  }  
]  
}
